class InputBuffer:
    def __init__(self, buffer_frames=10):
        self.buffer = []
        self.buffer_frames = buffer_frames
        self.frame = 0

    def record(self, inputs):
        self.buffer.append({'frame': self.frame, 'inputs': inputs})
        self.frame += 1
        # Remove old inputs:
        self.buffer = [b for b in self.buffer
                       if self.frame - b['frame'] < self.buffer_frames]

    def check_sequence(self, sequence):
        recent_inputs = [b['inputs'] for b in self.buffer]
        seq_index = 0
        for inputs in recent_inputs:
            if sequence[seq_index] in inputs:
                seq_index += 1
                if seq_index == len(sequence):
                    return True
        return False

