def graph_coloring(graph, num_colors):
    colors = {}

    def is_valid(node, color):
        for neighbor in graph.get(node, []):
            if colors.get(neighbor) == color:
                return False
        return True

    def backtrack(nodes, idx):
        if idx == len(nodes):
            return True
        node = nodes[idx]
        for color in range(num_colors):
            if is_valid(node, color):
                colors[node] = color
                if backtrack(nodes, idx + 1):
                    return True
                del colors[node]
        return False

    nodes = list(graph.keys())
    if backtrack(nodes, 0):
        return colors
    return None  # no solution with num_colors

def lcs(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n+1) for _ in range(m+1)]

    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Reconstruct the sequence:
    result = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            result.append(s1[i-1])
            i -= 1; j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    return ''.join(reversed(result))

def max_sum_subarray(nums, k):
    # Find max sum of any k consecutive elements
    window_sum = sum(nums[:k])
    max_sum = window_sum

    for i in range(k, len(nums)):
        window_sum += nums[i] - nums[i-k]  # slide: add new, remove old
        max_sum = max(max_sum, window_sum)

    return max_sum

# Variable size window — longest substring without repeating chars:
def longest_unique_substring(s):
    start = 0
    seen = {}
    max_len = 0
    for end, char in enumerate(s):
        if char in seen and seen[char] >= start:
            start = seen[char] + 1
        seen[char] = end
        max_len = max(max_len, end - start + 1)
    return max_len

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # path compression
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False  # already connected
        # Union by rank:
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        self.components -= 1
        return True

    def connected(self, x, y):
        return self.find(x) == self.find(y)

