def word_search(board, word):
    rows, cols = len(board), len(board[0])

    def dfs(r, c, idx, visited):
        if idx == len(word):
            return True
        if not (0 <= r < rows and 0 <= c < cols):
            return False
        if (r, c) in visited or board[r][c] != word[idx]:
            return False

        visited.add((r, c))
        found = any(
            dfs(r+dr, c+dc, idx+1, visited)
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]
        )
        visited.remove((r, c))
        return found

    return any(
        dfs(r, c, 0, set())
        for r in range(rows)
        for c in range(cols)
    )

def is_balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return len(stack) == 0

