class FileProcessor:
    def __init__(self, watch_dir, process_fn, extension='.txt'):
        self.watch_dir = Path(watch_dir)
        self.process = process_fn
        self.extension = extension
        self.processed = set()

    def scan(self):
        for filepath in self.watch_dir.glob(f'*{self.extension}'):
            if filepath not in self.processed:
                try:
                    self.process(filepath)
                    self.processed.add(filepath)
                    print(f'Processed: {filepath.name}')
                except Exception as e:
                    print(f'Error processing {filepath.name}: {e}')

    def watch(self, interval=1.0):
        print(f'Watching {self.watch_dir}...')
        while True:
            self.scan()
            time.sleep(interval)

