class BehaviorNode:
    SUCCESS = 'success'
    FAILURE = 'failure'
    RUNNING = 'running'

    def run(self, entity): raise NotImplementedError

class Sequence(BehaviorNode):
    def __init__(self, *children):
        self.children = children

    def run(self, entity):
        for child in self.children:
            result = child.run(entity)
            if result != self.SUCCESS:
                return result
        return self.SUCCESS

class Selector(BehaviorNode):
    def __init__(self, *children):
        self.children = children

    def run(self, entity):
        for child in self.children:
            result = child.run(entity)
            if result == self.SUCCESS:
                return result
        return self.FAILURE

class Condition(BehaviorNode):
    def __init__(self, fn):
        self.fn = fn
    def run(self, entity):
        return self.SUCCESS if self.fn(entity) else self.FAILURE

class Action(BehaviorNode):
    def __init__(self, fn):
        self.fn = fn
    def run(self, entity):
        return self.fn(entity)

