import math
import random

class PerlinNoise:
    def __init__(self, seed=None):
        if seed is not None:
            random.seed(seed)
        self.perm = list(range(256))
        random.shuffle(self.perm)
        self.perm *= 2

    def fade(self, t):
        return t * t * t * (t * (t * 6 - 15) + 10)

    def lerp(self, t, a, b):
        return a + t * (b - a)

    def grad(self, hash_val, x, y):
        h = hash_val & 3
        u = x if h < 2 else y
        v = y if h < 2 else x
        return (u if h & 1 == 0 else -u) + (v if h & 2 == 0 else -v)

    def noise(self, x, y):
        X = int(x) & 255
        Y = int(y) & 255
        x -= int(x)
        y -= int(y)
        u = self.fade(x)
        v = self.fade(y)
        a = self.perm[X] + Y
        b = self.perm[X + 1] + Y
        return self.lerp(v,
            self.lerp(u, self.grad(self.perm[a], x, y),
                        self.grad(self.perm[b], x-1, y)),
            self.lerp(u, self.grad(self.perm[a+1], x, y-1),
                        self.grad(self.perm[b+1], x-1, y-1)))

