class Cutscene:
    def __init__(self):
        self.steps = []
        self.current_step = 0
        self.active = False
        self.step_timer = 0

    def add_step(self, action_fn, duration):
        self.steps.append({'action': action_fn, 'duration': duration})
        return self

    def start(self):
        self.current_step = 0
        self.active = True
        self.step_timer = 0
        if self.steps:
            self.steps[0]['action']()

    def update(self, dt):
        if not self.active:
            return
        self.step_timer += dt
        current = self.steps[self.current_step]
        if self.step_timer >= current['duration']:
            self.step_timer = 0
            self.current_step += 1
            if self.current_step >= len(self.steps):
                self.active = False
            else:
                self.steps[self.current_step]['action']()

