class QuestObjective:
    description: str
    check_fn: Callable
    completed: bool = False

@dataclass
class Quest:
    name: str
    description: str
    objectives: List[QuestObjective]
    reward_fn: Optional[Callable] = None
    status: QuestStatus = QuestStatus.INACTIVE

    def activate(self):
        self.status = QuestStatus.ACTIVE

