        for obj in self.objectives:
            if not obj.completed:
                obj.completed = obj.check_fn(game_state)
        if all(o.completed for o in self.objectives):
            self.status = QuestStatus.COMPLETED
            if self.reward_fn:
                self.reward_fn()

